import React, { useEffect, useState } from 'react';
import axios from 'axios';

export default function AnalyticsDashboard() {
  const [tot, setTot]   = useState(0);
  const [avail, setAvail] = useState(0);
  const [rate, setRate] = useState('0%');

  useEffect(()=>{
    Promise.all([
      axios.get(`${process.env.REACT_APP_API_URL}/api/delivery`),
      axios.get(`${process.env.REACT_APP_API_URL}/api/drivers`)
    ]).then(([dR,drR])=>{
      const dels   = dR.data;
      const drs    = drR.data;
      const done   = dels.filter((x:any)=>x.status==='Delivered').length;
      setTot(dels.length);
      setAvail(drs.filter((x:any)=>x.isAvailable).length);
      setRate(dels.length?`${Math.round(done/dels.length*100)}%`:'0%');
    });
  },[]);

  return (
    <div style={{padding:20}}>
      <h3>Analytics</h3>
      <p>Total Deliveries: {tot}</p>
      <p>Available Drivers: {avail}</p>
      <p>Success Rate: {rate}</p>
    </div>
  );
}
